def emit(path):
    out = ["; Generated by tools/mkspeech.py - DO NOT EDIT. Edit MESSAGES there.",
           ";",
           "; One phoneme per byte, %SSPPPPPP: the OS's phoneme index in the low six",
           "; bits, the length and stress in the top two; a low six bits of zero ends",
           "; the string. Read straight out of the message bank by spk_say, which",
           "; copies it - see src/speech.s.",
           ""]
    spoken = 0
    phbytes = 0
    for idx, (name, text, u) in enumerate(MESSAGES):
        if u is None:
            continue
        assert len(u) < SPK_BUF_LEN, \
            "%s is %d phonemes; the OS buffer holds %d" \
            % (name, len(u), SPK_BUF_LEN - 1)
        spoken += 1
        phbytes += len(u) + 1
        out.append('; %s (id %d) - "%s": %d phonemes, roughly %d frames'
                   % (name, idx, text, len(u), 4 * len(u)))
        out.append("%s_PH:" % name)
        for ph, ss, cm in u:
            line = "        .byte   %-11s| SPK_PH_%-4s" % (ss, ph)
            out.append(line.rstrip() + ("   ; " + cm if cm else ""))
        out.append("        .byte   $00")
        out.append("")

    out.append("; The pointer table: one entry per IM_* id, IN ID ORDER, $00 where the")
    out.append("; message is not spoken. Read INSIDE the message bank's window (speech.s).")
    for half, tab in (("<", "LO"), (">", "HI")):
        out.append("SPK_%s:" % tab)
        for idx, (name, text, u) in enumerate(MESSAGES):
            ref = ("%s%s_PH" % (half, name)) if u else "$00"
            out.append("        .byte   %-16s; %2d %s" % (ref, idx, text))
    out.append("")
    out.append("SPK_IDS     = %d                 ; ...and how many, for speech.s's assert"
               % len(MESSAGES))
    out.append("")
    out.append("; The ending's lines (ENDING in mkspeech.py), spoken by gate.s sector_frame.")
    for i, (text, u) in enumerate(ENDING):
        assert len(u) < SPK_BUF_LEN, "ENDING %d is too long" % i
        out.append('; "%s": %d phonemes' % (text, len(u)))
        out.append("SPK_END%d_PH:" % i)
        for ph, ss, cm in u:
            line = "        .byte   %-11s| SPK_PH_%-4s" % (ss, ph)
            out.append(line.rstrip() + ("   ; " + cm if cm else ""))
        out.append("        .byte   $00")
    for half, tab in (("<", "LO"), (">", "HI")):
        out.append("SPK_END_%s:" % tab)
        for i, (text, u) in enumerate(ENDING):
            out.append("        .byte   %s%s" % (half, "SPK_END%d_PH" % i))
    out.append("SPK_END_N   = %d" % len(ENDING))
    with open(path, "w", newline="\r\n") as f:
        f.write("\n".join(out) + "\n")
    return spoken, phbytes


if __name__ == '__main__':
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    spoken, phbytes = emit(os.path.join(root, 'src', 'speech.inc'))
    for name, text, u in MESSAGES:
        if u:
            print('  %-14s "%s" - %d phonemes' % (name, text, len(u)))
    print('src/speech.inc written: %d of %d messages speak, %d bytes of phonemes '
          'and %d of pointers' % (spoken, len(MESSAGES), phbytes, 2 * len(MESSAGES)))
